def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    actd = ctx.get('action') or {}
    if not isinstance(task, dict):
        task = {}
    if not isinstance(world, dict):
        world = {}
    if not isinstance(actd, dict):
        actd = {}
    target = str(task.get('target_type') or ctx.get('task.target_type') or '').lower()
    dest = str(task.get('destination_type') or ctx.get('task.destination_type') or '').lower()
    task_type = str(task.get('task_type') or ctx.get('task.task_type') or '').lower()
    act = ''
    try:
        act = actd.get('final_action') or actd.get('normalized') or actd.get('raw') or ''
    except Exception:
        act = ''
    if not act:
        act = str(ctx.get('action.final_action') or ctx.get('action.normalized') or ctx.get('action.raw') or '')
    act = act.lower()
    obs = str(ctx.get('observation') or '').lower()
    inv = world.get('inventory') or []
    if not isinstance(inv, list):
        inv = []
    inv_text = ' '.join([str(x).lower() for x in inv])
    verb = ''
    if 'clean' in task_type:
        verb = 'clean'
    elif 'heat' in task_type:
        verb = 'heat'
    elif 'cool' in task_type:
        verb = 'cool'
    elif 'slice' in task_type:
        verb = 'slice'
    if verb and target and (act.startswith(verb + ' ') and target in act) and (verb + 'ed' in obs or 'nothing happens' in obs or 'you use' in obs):
        nb['transform_done'] = True
    pc = world.get('placed_count')
    try:
        pc = int(pc or 0)
    except Exception:
        pc = 0
    if target and act.startswith('put ') and target in act and (not dest or dest in act) and ('you put' in obs or 'put the' in obs):
        if pc < nb.get('placed_count', 0) + 1:
            pc = nb.get('placed_count', 0) + 1
        if ' in ' in act:
            loc = act.split(' in ', 1)[1]
            locs = world.get('placed_locations') or []
            if not isinstance(locs, list):
                locs = []
            if loc and loc not in [str(x).lower() for x in locs]:
                locs.append(loc)
            world['placed_locations'] = locs
    nb['placed_count'] = pc
    holding_target = bool(target and target in inv_text)
    wrong_inv = bool((not target) or (target not in inv_text) and inv_text and 'nothing' not in inv_text and 'empty' not in inv_text and 'none' not in inv_text)
    can_take = bool(target) and any(a.startswith('take ') and target in a for a in (ctx.get('admissible') or []))
    can_transform = bool(verb) and target and any(a.startswith(verb + ' ') and target in a for a in (ctx.get('admissible') or []))
    can_put = bool(target) and any(a.startswith('put ') and target in a and (not dest or dest in a) for a in (ctx.get('admissible') or []))
    has_put = bool(target) and any(a.startswith('put ') and target in a for a in (ctx.get('admissible') or []))
    if wrong_inv:
        stage = 'wrong_inventory'
    elif holding_target and verb and not nb.get('transform_done'):
        stage = 'transform'
    elif holding_target and can_put and target and target in act:
        stage = 'put_target'
    elif holding_target and has_put and target and target in act:
        stage = 'go_destination'
    elif holding_target:
        stage = 'take_target'
    elif can_take:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = task_type
    nb['verb'] = verb
    nb['holding_target'] = holding_target
    nb['wrong_inventory'] = wrong_inv
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('verb') or ''
    task_type = nb.get('task_type') or ''
    message = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory appears to hold a non-target item. Do not place it as the goal object; recover by setting it aside if allowed, then search for the requested ' + target + '.'
    elif stage == 'transform' and verb:
        msg = 'Before placing, use the admissible ' + verb + ' action on the ' + target + '. Raw target placement is not enough for tasks requiring ' + verb + '.'
    elif stage == 'take_target':
        msg = 'A requested ' + target + ' is visible or reachable; take it before opening more places or continuing to search.'
    elif stage == 'go_destination' and verb:
        msg = 'The ' + target + ' has been ' + verb + 'ed. Now carry it to the ' + dest + ' and use the put action there.'
    elif stage == 'put_target':
        msg = 'The requested ' + target + ' is at the ' + dest + '; use the admissible put action now instead of leaving or searching elsewhere.'
    elif 'two' in task_type and nb.get('placed_count', 0) > 0 and stage in ('find_target', 'take_target'):
        msg = 'One ' + target + ' is already placed. Do not take it back; find another ' + target + ' and use the same ' + dest + ' if possible.'
    if not message:
        return None
    key = stage + ':' + message[:90]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}
